99	// =========================================================================
100	//  Vec4 alignment check (host-side)
101	// =========================================================================
102	
103	__host__ __forceinline__ bool is_vec4_alignable(
104	    const void* p, int64_t numel
105	) {
106	    return ((reinterpret_cast<uintptr_t>(p) & 0xF) == 0) && (numel % 4 == 0);
107	}
