109	// =========================================================================
110	//  Warp-level sum reduction (butterfly via __shfl_down_sync)
111	// =========================================================================
112	
113	__device__ __forceinline__ float warp_reduce_sum_f32(float v) {
114	    for (int offset = 16; offset > 0; offset >>= 1) {
115	        v += __shfl_down_sync(0xffffffff, v, offset);
116	    }
117	    return v;
118	}
119	
120	// =========================================================================
121	//  Block-level sum reduction: warp reduce + shared-memory tree + warp reduce.
122	//  Uses up to 32 floats of smem (one per warp).
123	// =========================================================================
124	
125	__device__ __forceinline__ float block_reduce_sum_f32(float v) {
126	    __shared__ float smem[32];
127	    const int tid = threadIdx.x;
128	    const int warp = tid / 32;
129	    const int lane = tid & 31;
130	
131	    float w = warp_reduce_sum_f32(v);
132	    if (lane == 0) smem[warp] = w;
133	    __syncthreads();
134	
135	    int n_warps = (blockDim.x + 31) / 32;
136	    if (warp == 0) {
137	        float x = (lane < n_warps) ? smem[lane] : 0.0f;
138	        x = warp_reduce_sum_f32(x);
139	        if (lane == 0) smem[0] = x;
140	    }
141	    __syncthreads();
142	    return smem[0];
143	}
144	
145	// =========================================================================
146	//  Block-level sum reduction of TWO floats in one pass (shared warp-tree).
147	//  Reduces a and b together: one shared-memory tile (2 floats/warp) and a
148	//  single pair of __syncthreads, instead of two back-to-back
149	//  block_reduce_sum_f32 calls (which serialize on the same static smem).
150	//  Used by the prodigy (r, s) reduce. Every thread returns the block sums.
151	// =========================================================================
152	
153	__device__ __forceinline__ void block_reduce_sum2_f32(
154	    float a, float b, float& a_out, float& b_out
155	) {
156	    __shared__ float smem_a[32];
157	    __shared__ float smem_b[32];
158	    const int tid = threadIdx.x;
159	    const int warp = tid / 32;
160	    const int lane = tid & 31;
161	
162	    a = warp_reduce_sum_f32(a);
163	    b = warp_reduce_sum_f32(b);
164	    if (lane == 0) { smem_a[warp] = a; smem_b[warp] = b; }
165	    __syncthreads();
166	
167	    const int n_warps = (blockDim.x + 31) / 32;
168	    if (warp == 0) {
169	        float xa = (lane < n_warps) ? smem_a[lane] : 0.0f;
170	        float xb = (lane < n_warps) ? smem_b[lane] : 0.0f;
171	        xa = warp_reduce_sum_f32(xa);
172	        xb = warp_reduce_sum_f32(xb);
173	        if (lane == 0) { smem_a[0] = xa; smem_b[0] = xb; }
174	    }
175	    __syncthreads();
176	    a_out = smem_a[0];
177	    b_out = smem_b[0];
178	}
179	
180	// =========================================================================
181	//  Warp-level u32 sum reduction (§4.1 PTX maximization).
182	//  Integer reductions use the single-instruction `redux.sync.add.u32`
183	//  warp collective on Ampere/Hopper (sm_80+), which replaces the 5-step
184	//  shuffle-xor butterfly with one instruction. Every lane in the (fully
185	//  active) warp receives the full-warp sum. A shuffle-tree fallback keeps
186	//  the helper compiling/working on pre-Ampere arches in the codegen matrix.
187	//
188	//  NOTE: integer-only. FLOAT redux (`redux.sync.{add,min,max}.f32`) is
189	//  Blackwell-only (sm_100+) and out of scope — float reductions stay on the
190	//  shuffle tree (warp_reduce_sum_f32 above).
191	// =========================================================================
192	
193	__device__ __forceinline__ unsigned warp_reduce_add_u32(unsigned v) {
194	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
195	    unsigned r;
196	    asm volatile("redux.sync.add.u32 %0, %1, 0xffffffff;" : "=r"(r) : "r"(v));
197	    return r;  // every lane gets the full-warp sum
198	#else
199	    // shuffle-tree fallback (pre-Ampere)
200	    for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffff, v, o);
201	    return v;
202	#endif
203	}
204	
205	// =========================================================================
206	//  Block-level u32 sum reduction: warp reduce + shared-memory tree + warp
207	//  reduce. Mirrors block_reduce_sum_f32 exactly (32 u32 of smem, one per
208	//  warp; same __syncthreads placement) but uses the redux.sync warp reducer.
209	// =========================================================================
210	
211	__device__ __forceinline__ unsigned block_reduce_add_u32(unsigned v) {
212	    __shared__ unsigned smem[32];
213	    const int tid = threadIdx.x;
214	    const int warp = tid / 32;
215	    const int lane = tid & 31;
216	
217	    unsigned w = warp_reduce_add_u32(v);
218	    if (lane == 0) smem[warp] = w;
219	    __syncthreads();
220	
221	    int n_warps = (blockDim.x + 31) / 32;
222	    if (warp == 0) {
223	        unsigned x = (lane < n_warps) ? smem[lane] : 0u;
224	        x = warp_reduce_add_u32(x);
225	        if (lane == 0) smem[0] = x;
226	    }
227	    __syncthreads();
228	    return smem[0];
229	}
