241	//  Non-temporal load / store (bypass L2 for read-once optimizer state).
242	//  Implemented in common/platform.h; wrapped here for legibility.
243	// =========================================================================
244	
245	__device__ __forceinline__ float ldg_f32(const float* ptr) {
246	    return __ldg(ptr);
