85	template <typename ParamT, typename GradT>
86	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
87	prodigy_reduce_kernel(
88	    const ParamT* param, const ParamT* param_init, const GradT* grad,
89	    float d_prev,
90	    float* r_partial, float* s_partial,
91	    int64_t N
92	) {
93	    float r_local = 0.0f, s_local = 0.0f;
94	    const int64_t stride = prim::grid_stride();
95	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
96	        SG_SANITIZE_GRAD_INPLACE(grad, i);
97	        prodigy_partials_step(param, param_init, grad, d_prev, i,
98	                              r_local, s_local);
99	    }
100	    // Single fused two-value block reduction (one shared tile + one barrier
101	    // pair) → ONE atomicAdd per partial per block, instead of two separate
102	    // block reductions.
103	    float r_block, s_block;
104	    prim::block_reduce_sum2_f32(r_local, s_local, r_block, s_block);
105	    if (threadIdx.x == 0) {
106	        atomicAdd(r_partial, r_block);
107	        atomicAdd(s_partial, s_block);
108	    }
109	}
110	
111	// Fused reduce + d-update for the SINGLE-tensor path: the LAST block to finish
112	// (last_block_finished + the gridDim counter) reads the fully-accumulated
113	// (r, s) partials and writes d_t directly — folding away the separate
114	// <<<1,1>>> prodigy_update_d_kernel launch. block_done_counter must be a
115	// device scalar zeroed before launch. The multi-tensor path keeps the separate
116	// d-update kernel (it accumulates across many launches before the update).
117	template <typename ParamT, typename GradT>
118	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
119	prodigy_reduce_and_update_d_kernel(
120	    const ParamT* param, const ParamT* param_init, const GradT* grad,
121	    float d_prev,
122	    float* r_partial, float* s_partial, float* d_t,
123	    unsigned* block_done_counter,
124	    int64_t N, int total_blocks
125	) {
126	    float r_local = 0.0f, s_local = 0.0f;
127	    const int64_t stride = prim::grid_stride();
128	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
129	        SG_SANITIZE_GRAD_INPLACE(grad, i);
130	        prodigy_partials_step(param, param_init, grad, d_prev, i,
131	                              r_local, s_local);
132	    }
133	    float r_block, s_block;
134	    prim::block_reduce_sum2_f32(r_local, s_local, r_block, s_block);
135	    if (threadIdx.x == 0) {
136	        atomicAdd(r_partial, r_block);
137	        atomicAdd(s_partial, s_block);
138	    }
139	    // __threadfence so the last block sees the completed atomic results.
140	    __threadfence();
141	    if (prim::last_block_finished(block_done_counter, total_blocks)) {
142	        if (threadIdx.x == 0) {
143	            *d_t = prodigy_update_d(d_prev, *r_partial, *s_partial);
144	        }
145	    }
146	}
147	
148	// §3.2 DSMEM cluster variant of the (r, s) partial reduce. Launched with a
149	// thread-block cluster (__cluster_dims__) so the whole reduction fits in ONE
150	// cluster; the cross-block sum is done via DSMEM (map_shared_rank + cl.sync)
151	// instead of a global atomicAdd. Only correct when the launch grid == the
152	// cluster volume (one cluster covers every block); the host launcher enforces
153	// that before selecting this kernel. Block 0 writes the final sum directly.
154	//
155	// Gated behind ENABLE_DSMEM_REDUCE at the call site; when the toggle is off,
156	// this kernel is never launched (the atomic kernel above is used) — so the
157	// cluster machinery adds NO cost on the default path.
158	#if defined(ENABLE_DSMEM_REDUCE) && (ENABLE_DSMEM_REDUCE != 0)
159	template <typename ParamT, typename GradT>
160	__global__ void __cluster_dims__(
161	    SG_TUNED_CLUSTER_SHAPE_0, SG_TUNED_CLUSTER_SHAPE_1, SG_TUNED_CLUSTER_SHAPE_2)
162	prodigy_reduce_dsmem_kernel(
163	    const ParamT* param, const ParamT* param_init, const GradT* grad,
164	    float d_prev,
165	    float* r_partial, float* s_partial,
166	    int64_t N
167	) {
168	    // One shared slot per reduced quantity for this block's published partial.
169	    __shared__ float r_slot;
170	    __shared__ float s_slot;
171	
172	    float r_local = 0.0f, s_local = 0.0f;
173	    const int64_t stride = prim::grid_stride();
174	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
175	        SG_SANITIZE_GRAD_INPLACE(grad, i);
176	        prodigy_partials_step(param, param_init, grad, d_prev, i,
177	                              r_local, s_local);
178	    }
179	    // Full thread->warp->block->cluster tree; every block gets the same sum.
180	    float r_sum = prim::cluster_reduce_sum_f32_dsmem(r_local, &r_slot);
181	    float s_sum = prim::cluster_reduce_sum_f32_dsmem(s_local, &s_slot);
182	
183	    // One block (rank 0, thread 0) publishes the final result — no atomic.
184	    if (blockIdx.x == 0 && threadIdx.x == 0) {
185	        *r_partial = r_sum;
186	        *s_partial = s_sum;
187	    }
188	}
189	#endif  // ENABLE_DSMEM_REDUCE
190	
191	__global__ void prodigy_update_d_kernel(
192	    float* d_t, const float* r_sum, const float* s_sum, float d_prev
193	) {
194	    if (blockIdx.x == 0 && threadIdx.x == 0) {
195	        *d_t = prodigy_update_d(d_prev, *r_sum, *s_sum);
196	    }
197	}
198	
199	template <typename ParamT, typename GradT, int UNROLL>
200	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
201	prodigy_apply_kernel(
202	    ParamT* param, float* exp_avg, float* exp_avg_sq, float* s_track,
203	    const GradT* grad, const float* d_ptr,
204	    float beta1, float beta2, float eps, float wd,
205	    float bc1, float bc2, int64_t N
206	) {
207	    const float d = *d_ptr;
208	    const int64_t stride = prim::grid_stride() * UNROLL;
209	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
210	    for (int64_t base = base0; base < N; base += stride) {
211	        #pragma unroll
212	        for (int u = 0; u < UNROLL; ++u) {
213	            const int64_t i = base + u;
214	            if (i < N) {
215	                SG_SANITIZE_GRAD_INPLACE(grad, i);
216	                prodigy_apply_step(param, exp_avg, exp_avg_sq, s_track, grad,
217	                                   d, beta1, beta2, eps, wd, bc1, bc2, i);
218	            }
219	        }
220	    }
221	}
222	
223	// FP32 vec4 apply: float4 traffic, canonical prodigy_apply_step CALLED 4×.
224	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
225	prodigy_apply_kernel_vec4_fp32(
226	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4, float4* s_track4,
227	    const float4* grad4, const float* d_ptr,
228	    float beta1, float beta2, float eps, float wd,
229	    float bc1, float bc2, int64_t N4
230	) {
231	    const float d = *d_ptr;
232	    const int64_t stride = prim::grid_stride();
233	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
234	        float4 p  = prim::ld_f32v4(param4 + i);
235	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
236	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
237	        float4 st = prim::ld_f32v4(s_track4 + i);
238	        float4 g  = prim::ldg_f32v4(grad4 + i);
239	        ::grokking::sm90::sg_sanitize_grad4(g);
240	        #pragma unroll
241	        for (int u = 0; u < 4; ++u) {
242	            prodigy_apply_step(&p.x, &m.x, &v.x, &st.x, &g.x,
243	                               d, beta1, beta2, eps, wd, bc1, bc2, u);
244	        }
245	        prim::st_f32v4(param4 + i, p);
246	        prim::st_f32v4(exp_avg4 + i, m);
247	        prim::st_f32v4(exp_avg_sq4 + i, v);
248	        prim::st_f32v4(s_track4 + i, st);
249	    }
250	}
251	
252	void launch_prodigy_step(
253	    torch::Tensor& param,
254	    torch::Tensor& exp_avg,
255	    torch::Tensor& exp_avg_sq,
256	    torch::Tensor& s_track,
257	    const torch::Tensor& param_init,
258	    const torch::Tensor& grad,
259	    torch::Tensor& d_t,
260	    torch::Tensor& r_partial,
261	    torch::Tensor& s_partial,
262	    float d_prev,
263	    float beta1, float beta2, float eps, float wd,
264	    float bc1, float bc2
265	) {
266	    const int64_t N = param.numel();
267	    if (N == 0) return;
268	
269	    auto stream = at::cuda::getCurrentCUDAStream().stream();
270	
271	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
272	    prim::L2PersistScope l2(stream,
273	        exp_avg.data_ptr(), exp_avg.nbytes(),
274	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
275	
276	    const int block = SG_TUNED_BLOCK_SIZE;
277	    const int grid = static_cast<int>(
278	        std::min<int64_t>(65535, (N + block - 1) / block));
279	
280	    r_partial.zero_();
281	    s_partial.zero_();
282	
283	#if defined(ENABLE_DSMEM_REDUCE) && (ENABLE_DSMEM_REDUCE != 0)
284	    // §3.2 DSMEM cross-CTA path: only valid when the ENTIRE reduction grid fits
285	    // in ONE thread-block cluster (one cluster covers every block, so the
286	    // cross-block sum can ride DSMEM instead of a global atomic). When the grid
287	    // is larger than the cluster volume, fall back to the atomic kernel below.
288	    constexpr int kClusterVol = prodigy_detail::kClusterVolume;
289	    const bool dsmem_fits = (kClusterVol > 1) && (grid <= kClusterVol);
290	    if (dsmem_fits) {
291	        // Launch exactly kClusterVol blocks = one full cluster; the
292	        // __cluster_dims__ attribute supplies the cluster shape. The grid-
293	        // stride loop in the kernel still covers all N elements.
294	        AT_DISPATCH_FLOATING_TYPES_AND2(
295	            at::ScalarType::Half, at::ScalarType::BFloat16,
296	            param.scalar_type(), "prodigy_reduce_dsmem", [&] {
297	                prodigy_reduce_dsmem_kernel<scalar_t, scalar_t>
298	                    <<<kClusterVol, block, 0, stream>>>(
299	                    param.data_ptr<scalar_t>(),
300	                    param_init.data_ptr<scalar_t>(),
301	                    grad.data_ptr<scalar_t>(),
302	                    d_prev,
303	                    r_partial.data_ptr<float>(),
304	                    s_partial.data_ptr<float>(),
305	                    N);
306	                SG_LAUNCH_CHECK(stream);
307	            });
308	        // DSMEM path wrote the final (r, s) directly; do the d-update on one
309	        // thread (the cluster kernel cannot use the last-block fold).
310	        prodigy_update_d_kernel<<<1, 1, 0, stream>>>(
311	            d_t.data_ptr<float>(),
312	            r_partial.data_ptr<float>(),
313	            s_partial.data_ptr<float>(),
314	            d_prev);
315	        SG_LAUNCH_CHECK(stream);
316	    } else
317	#endif  // ENABLE_DSMEM_REDUCE
318	    {
319	        // Atomic reduce + last-block d-update fold: the reduce kernel itself
320	        // writes d_t from the completed (r, s) partials — no separate <<<1,1>>>.
321	        auto counter = torch::zeros({1},
322	            torch::TensorOptions().device(param.device()).dtype(torch::kInt32));
323	        AT_DISPATCH_FLOATING_TYPES_AND2(
324	            at::ScalarType::Half, at::ScalarType::BFloat16,
325	            param.scalar_type(), "prodigy_reduce_update_d", [&] {
326	                prodigy_reduce_and_update_d_kernel<scalar_t, scalar_t>
327	                    <<<grid, block, 0, stream>>>(
328	                    param.data_ptr<scalar_t>(),
329	                    param_init.data_ptr<scalar_t>(),
330	                    grad.data_ptr<scalar_t>(),
331	                    d_prev,
332	                    r_partial.data_ptr<float>(),
333	                    s_partial.data_ptr<float>(),
334	                    d_t.data_ptr<float>(),
335	                    reinterpret_cast<unsigned*>(counter.data_ptr<int>()),
336	                    N, grid);
337	                SG_LAUNCH_CHECK(stream);
338	            });
339	    }
340	
341	    const bool apply_fp32 = param.scalar_type() == torch::kFloat32 &&
342	                            grad.scalar_type() == torch::kFloat32;
343	    if (SG_TUNED_VEC_WIDTH == 4 && apply_fp32 &&
344	        prim::is_vec4_alignable(param.data_ptr(), N) &&
345	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
346	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
347	        prim::is_vec4_alignable(s_track.data_ptr(), N) &&
348	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
349	        const int64_t N4 = N / 4;
350	        const int grid4 = static_cast<int>(
351	            std::min<int64_t>(65535, (N4 + block - 1) / block));
352	        prodigy_apply_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
353	            reinterpret_cast<float4*>(param.data_ptr<float>()),
354	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
355	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
356	            reinterpret_cast<float4*>(s_track.data_ptr<float>()),
357	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
358	            d_t.data_ptr<float>(),
359	            beta1, beta2, eps, wd, bc1, bc2, N4);
360	        SG_LAUNCH_CHECK(stream);
361	        return;
362	    }
363	
364	    AT_DISPATCH_FLOATING_TYPES_AND2(
365	        at::ScalarType::Half, at::ScalarType::BFloat16,
366	        param.scalar_type(), "prodigy_apply", [&] {
367	            prodigy_apply_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
368	                <<<grid, block, 0, stream>>>(
369	                param.data_ptr<scalar_t>(),
370	                exp_avg.data_ptr<float>(),
371	                exp_avg_sq.data_ptr<float>(),
372	                s_track.data_ptr<float>(),
373	                grad.data_ptr<scalar_t>(),
374	                d_t.data_ptr<float>(),
375	                beta1, beta2, eps, wd, bc1, bc2, N);
376	            SG_LAUNCH_CHECK(stream);
377	        });
378	}
