443	// Multi-tensor fused reduce + step: accumulate the Prodigy D-estimate's
444	// PERSISTENT EMA numerator/denominator across all tensors, update d, then apply
445	// the Prodigy update to each.
446	//
447	// Canonical persistent-EMA estimator (Mishchenko & Defazio 2023 / prodigyopt):
448	// r_num_buf and s_den_buf are running EMAs that PERSIST across steps (carried in
449	// by the host from the Python optimizer). At step start they are decayed by
450	// beta3 = sqrt(beta2) — NOT zeroed — then this step's per-tensor reductions
451	//   r += Σ g·(p_init−p)·d²     (numerator, prodigy_partials_step)
452	//   s += Σ d²·|g|              (denominator L1, prodigy_partials_step)
453	// are atomic-added on top (so r_ema = beta3·r_ema + Σd²·…). d is then
454	//   d = max(d_prev, d_coef·r_ema/|s_ema|).
455	// This is the FIX for the instantaneous form (which zeroed r/s every step): the
456	// EMA averages post-memorization gradient-noise spikes over ~1/(1−beta3) steps
457	// so the `max()` no longer locks a single spike in → d PLATEAUS once the params
458	// stop drifting from init, instead of ratcheting up without bound (which had
459	// blown d past ~1e-1 and collapsed training back to random).
460	//
461	// prodigy.h's per-element/update device math is UNCHANGED (byte-identical): the
462	// EMA persistence + beta3 decay + d_coef scaling all live HERE in the host
463	// launcher, so the cross-backend math single-source hash does not move.
464	void launch_multi_tensor_prodigy_fused_reduce_step(
465	    std::vector<torch::Tensor>& params,
466	    std::vector<torch::Tensor>& grads,
467	    std::vector<torch::Tensor>& param_inits,
468	    std::vector<torch::Tensor>& exp_avgs,
469	    std::vector<torch::Tensor>& exp_avg_sqs,
470	    std::vector<torch::Tensor>& s_bufs,
471	    std::vector<float>& bc1s, std::vector<float>& bc2s,
472	    torch::Tensor d_lr_buf,
473	    torch::Tensor r_num_buf, torch::Tensor s_den_buf,
474	    float beta1, float beta2, float beta3, float lr, float wd, float eps,
475	    float d_coef
476	) {
477	    if (params.empty()) return;
478	    auto dev = params[0].device();
479	    float d_prev = d_lr_buf.item<float>();
480	
481	    auto stream = at::cuda::getCurrentCUDAStream().stream();
482	    const int block = SG_TUNED_BLOCK_SIZE;
483	
484	    // EMA decay of the PERSISTENT numerator/denominator (in place). The reduce
485	    // kernels below atomic-ADD this step's reduction on top, yielding
486	    //   r_ema <- beta3·r_ema + Σ d²·<g,p_init−p> ;  s_ema <- beta3·s_ema + Σ d²·|g|.
487	    r_num_buf.mul_(beta3);
488	    s_den_buf.mul_(beta3);
489	
490	    for (size_t i = 0; i < params.size(); i++) {
491	        const int64_t N = params[i].numel();
492	        if (N == 0) continue;
493	        const int grid = static_cast<int>(
494	        std::min<int64_t>(65535, (N + block - 1) / block));
495	        AT_DISPATCH_FLOATING_TYPES_AND2(
496	            at::ScalarType::Half, at::ScalarType::BFloat16,
497	            params[i].scalar_type(), "prodigy_mt_reduce", [&] {
498	                prodigy_reduce_kernel<scalar_t, scalar_t>
499	                    <<<grid, block, 0, stream>>>(
500	                    params[i].data_ptr<scalar_t>(),
501	                    param_inits[i].data_ptr<scalar_t>(),
502	                    grads[i].data_ptr<scalar_t>(),
503	                    d_prev,
504	                    r_num_buf.data_ptr<float>(),
505	                    s_den_buf.data_ptr<float>(), N);
506	                SG_LAUNCH_CHECK(stream);
507	            });
508	    }
509	
510	    // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d computes
511	    // max(d_prev, r/|s|) verbatim (prodigy.h, byte-identical), so d_coef is
512	    // folded by passing a SCALED numerator copy; the persistent r_num_buf keeps
513	    // the UNSCALED EMA (returned to Python). d_coef defaults to 1.0 (no-op).
514	    auto r_for_update = (d_coef == 1.0f)
515	        ? r_num_buf
516	        : (r_num_buf * d_coef).contiguous();
517	    prodigy_update_d_kernel<<<1, 1, 0, stream>>>(
518	        d_lr_buf.data_ptr<float>(),
519	        r_for_update.data_ptr<float>(),
520	        s_den_buf.data_ptr<float>(), d_prev);
521	    SG_LAUNCH_CHECK(stream);
522	
523	    for (size_t i = 0; i < params.size(); i++) {
524	        const int64_t N = params[i].numel();
525	        if (N == 0) continue;
526	        const int grid = static_cast<int>(
527	        std::min<int64_t>(65535, (N + block - 1) / block));
528	        AT_DISPATCH_FLOATING_TYPES_AND2(
529	            at::ScalarType::Half, at::ScalarType::BFloat16,
530	            params[i].scalar_type(), "prodigy_mt_apply", [&] {
531	                prodigy_apply_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
532	                    <<<grid, block, 0, stream>>>(
533	                    params[i].data_ptr<scalar_t>(),
