129	// FP32 vec4 update: float4 traffic, canonical muon_update_step CALLED 4×.
130	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
131	muon_update_kernel_vec4_fp32(
132	    float4* param4, const float4* orth4,
133	    float neg_lr_scale, float decay_factor, int64_t N4
134	) {
135	    const int64_t stride = prim::grid_stride();
136	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
137	        float4 p = prim::ld_f32v4(param4 + i);
138	        float4 o = prim::ldg_f32v4(orth4 + i);
139	        #pragma unroll
140	        for (int u = 0; u < 4; ++u) {
141	            muon_update_step(&p.x, &o.x, neg_lr_scale, decay_factor, u);
142	        }
143	        prim::st_f32v4(param4 + i, p);
144	    }
145	}
