246	// Fused Newton-Schulz combine + parameter update in a single pass.
247	// Y = a*X + b*AX + c*AAX (NS combine), then param -= lr_scale*Y + decay*param.
248	template <typename ParamT>
249	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
250	muon_ns_combine_update_kernel(
251	    ParamT* param, const float* X, const float* AX, const float* AAX,
252	    float a, float b, float c, float neg_lr_scale, float decay_factor, int64_t N
253	) {
254	    const int64_t stride = prim::grid_stride();
255	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
256	        float y = a * X[i] + b * AX[i] + c * AAX[i];
257	        float p = static_cast<float>(param[i]);
258	        // decay_factor = 1 - lr*wd is the RETENTION factor (host: muon_fused_step
259	        // bindings.cpp). The canonical update (muon.h / muon_update_step / the
260	        // non-fused launch_muon_update) is p*decay_factor + neg_lr_scale*orth.
261	        // The previous form p + neg_lr_scale*y - decay_factor*p == p*(1-decay_factor)
262	        // + ... inverted it (retained lr*wd≈2% of the param each step instead of
263	        // 98%), so the fused NS path silently destroyed the weights while the
264	        // non-fused path was correct.
265	        param[i] = static_cast<ParamT>(p * decay_factor + neg_lr_scale * y);
266	    }
267	}
