225	// Quantized Config-3: INT8 exp_avg, BF16 exp_avg_sq & ema.
226	// Dequantize → update in FP32 → re-quantize with stochastic rounding.
227	template <typename ParamT, typename GradT>
228	__global__ void grokadamw_q3_kernel(
229	    ParamT* param,
230	    int8_t* ea_int8, float* ea_scales,
231	    __nv_bfloat16* eas_bf16, __nv_bfloat16* ema_bf16,
232	    const GradT* grad,
233	    float alpha, float lamb,
234	    float lr, float beta1, float beta2, float eps, float wd,
235	    float bc1, float bc2, unsigned step, int64_t N, int block_size
236	) {
237	    const int64_t stride = prim::grid_stride();
238	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
239	        int64_t scale_idx = i / block_size;
240	        float scale = ea_scales[scale_idx];
241	        float ea_val = static_cast<float>(ea_int8[i]) * scale;
242	        float eas_val = __bfloat162float(eas_bf16[i]);
243	        float ema_val = __bfloat162float(ema_bf16[i]);
244	
245	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
246	        float p = static_cast<float>(param[i]);
247	
248	        float ema_new = alpha * ema_val + (1.0f - alpha) * g;
249	        float g_amp = g + lamb * ema_new;
250	        // Canonical bias-corrected Adam tail (single-source: algorithms/grokadamw.h).
251	        // g_eff = g_amp; moments come from the dequantized state, results are
252	        // re-quantized below — the float math itself lives once in the header.
253	        float m, v, p_new;
254	        grokadamw_adam_tail(g_amp, p, ea_val, eas_val,
255	                            lr, beta1, beta2, eps, wd, bc1, bc2,
256	                            m, v, p_new);
257	        param[i] = static_cast<ParamT>(p_new);
258	
259	        unsigned rng = hash_prng(step, static_cast<unsigned>(i));
260	        ea_int8[i] = ptx_int8_stochastic_round(m, scale, rng);
261	        eas_bf16[i] = float_to_bf16_stochastic(v, rng >> 16);
262	        ema_bf16[i] = float_to_bf16_stochastic(ema_new, rng ^ 0xDEADBEEFu);
263	    }
264	}
265	
266	void launch_fused_grokadamw_step_q3(
267	    torch::Tensor param,
268	    torch::Tensor exp_avg_int8, torch::Tensor exp_avg_scales,
269	    torch::Tensor exp_avg_sq_bf16, torch::Tensor ema_bf16,
270	    torch::Tensor grad,
271	    float alpha, float lamb,
272	    float beta1, float beta2,
273	    float lr, float weight_decay, float eps,
274	    float bc1, float bc2, unsigned global_step
275	) {
276	    const int64_t N = param.numel();
277	    if (N == 0) return;
278	
279	    auto stream = at::cuda::getCurrentCUDAStream().stream();
280	    const int block = SG_TUNED_BLOCK_SIZE;
281	    const int grid = static_cast<int>(
282	        std::min<int64_t>(65535, (N + block - 1) / block));
283	    // CEIL division: the kernel indexes ea_scales[i / q_block_size] for
284	    // i in [0, N). With floor division, a non-divisible N (N % numel != 0)
285	    // makes q_block_size too small so the largest i maps to scale_idx == numel
286	    // (one past the end → OOB read). ceil(N/numel) guarantees i/q_block_size
287	    // <= numel-1 for every i < N.
288	    const int q_block_size = std::max<int>(1, static_cast<int>(
289	        (N + exp_avg_scales.numel() - 1) / exp_avg_scales.numel()));
290	
291	    AT_DISPATCH_FLOATING_TYPES_AND2(
292	        at::ScalarType::Half, at::ScalarType::BFloat16,
293	        param.scalar_type(), "grokadamw_q3", [&] {
294	            grokadamw_q3_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
295	                param.data_ptr<scalar_t>(),
296	                exp_avg_int8.data_ptr<int8_t>(),
297	                exp_avg_scales.data_ptr<float>(),
298	                reinterpret_cast<__nv_bfloat16*>(exp_avg_sq_bf16.data_ptr()),
299	                reinterpret_cast<__nv_bfloat16*>(ema_bf16.data_ptr()),
300	                grad.data_ptr<scalar_t>(),
301	                alpha, lamb, lr, beta1, beta2, eps, weight_decay,
302	                bc1, bc2, global_step, N, q_block_size);
303	            SG_LAUNCH_CHECK(stream);
304	        });
305	}
