45	
46	// Minimum resident blocks/SM for the bandwidth-bound element-wise applies.
47	// Caps registers so occupancy stays high on the memory-bound path.
48	#ifndef SG_LION_MIN_BLOCKS
49	#define SG_LION_MIN_BLOCKS 4
50	#endif
51	
52	// SG_TUNED_UNROLL elements per iteration; the canonical lion_step is CALLED
53	// (math single-sourced) — the unroll only changes the loop structure the
54	// autotuner generates, not the math.
55	template <typename ParamT, typename GradT, int UNROLL>
56	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_LION_MIN_BLOCKS)
57	lion_kernel(
58	    ParamT* param, float* exp_avg,
59	    const GradT* grad,
60	    float lr, float beta1, float beta2, float wd, int64_t N
61	) {
62	    const int64_t stride = prim::grid_stride() * UNROLL;
63	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
64	    for (int64_t base = base0; base < N; base += stride) {
65	        #pragma unroll
66	        for (int u = 0; u < UNROLL; ++u) {
67	            const int64_t i = base + u;
68	            if (i < N) {
69	                SG_SANITIZE_GRAD_INPLACE(grad, i);
70	                lion_step(param, exp_avg, grad, lr, beta1, beta2, wd, i);
71	            }
72	        }
73	    }
74	}
