76	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_LION_MIN_BLOCKS)
77	lion_kernel_vec4_fp32(
78	    float4* param4, float4* exp_avg4, const float4* grad4,
79	    float lr, float beta1, float beta2, float wd, int64_t N4
80	) {
81	    const int64_t stride = prim::grid_stride();
82	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
83	        SG_SANITIZE_GRAD4_INPLACE(grad4, i);
84	        lion_step_vec4(param4, exp_avg4, grad4, lr, beta1, beta2, wd, i);
85	    }
86	}
