45	namespace sg { namespace sm90 {
46	
47	namespace prim = ::sg::sm90::primitives;
48	using ::sg::algorithms::neuralgrok_psi_forward;
49	using ::sg::algorithms::neuralgrok_apply_step;
50	using ::sg::algorithms::neuralgrok_adam_tail;
51	
52	// Compile-time hidden width specializations (H = 8, 16, 32, 64, 128).
53	constexpr int NG_H = 64;
54	
55	// Minimum resident blocks/SM. The psi-net forward is compute-heavy per element
56	// but the bound is still memory traffic on the Adam state; cap registers so
57	// occupancy stays high.
58	#ifndef SG_NEURALGROK_MIN_BLOCKS
59	#define SG_NEURALGROK_MIN_BLOCKS 4
60	#endif
61	
62	// Cooperatively stage the per-element psi-net weights (W1[H], b1[H], W2[H]) into
63	// shared memory ONCE per block, then hand the shared pointers to the canonical
64	// neuralgrok_psi_forward<H>. The same weights are read by every element this
65	// block processes; staging them removes the per-element re-read from GLOBAL
66	// inside the H-wide forward loop. NO math/signature change — the fn still takes
67	// const float* and is single-sourced in algorithms/neuralgrok.h.
68	template <int H>
69	__device__ __forceinline__ void ng_stage_psi_weights(
70	    const float* __restrict__ W1, const float* __restrict__ b1,
71	    const float* __restrict__ W2,
72	    float* sW1, float* sb1, float* sW2
73	) {
74	    for (int j = threadIdx.x; j < H; j += blockDim.x) {
75	        sW1[j] = W1[j];
76	        sb1[j] = b1[j];
77	        sW2[j] = W2[j];
78	    }
79	    __syncthreads();
80	}
81	
82	template <typename ParamT, typename GradT, int UNROLL>
83	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_NEURALGROK_MIN_BLOCKS)
84	neuralgrok_kernel(
85	    ParamT* param, float* exp_avg, float* exp_avg_sq,
86	    const GradT* grad,
87	    const float* W1, const float* b1, const float* W2, float b2,
88	    float alpha, float beta,
89	    float lr, float beta1_a, float beta2_a, float eps, float wd,
90	    float bc1, float bc2, int64_t N
91	) {
92	    __shared__ float sW1[NG_H];
93	    __shared__ float sb1[NG_H];
94	    __shared__ float sW2[NG_H];
95	    ng_stage_psi_weights<NG_H>(W1, b1, W2, sW1, sb1, sW2);
96	
97	    const int64_t stride = prim::grid_stride() * UNROLL;
98	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
99	    for (int64_t base = base0; base < N; base += stride) {
100	        #pragma unroll
101	        for (int u = 0; u < UNROLL; ++u) {
102	            const int64_t i = base + u;
103	            if (i < N) {
104	                SG_SANITIZE_GRAD_INPLACE(grad, i);
105	                const float ag = fabsf(static_cast<float>(grad[i]));
106	                const float s = neuralgrok_psi_forward<NG_H>(ag, sW1, sb1, sW2, b2);
107	                neuralgrok_apply_step(param, exp_avg, exp_avg_sq, grad, s,
108	                                      alpha, beta, lr, beta1_a, beta2_a, eps, wd,
109	                                      bc1, bc2, i);
110	            }
111	        }
112	    }
113	}
114	
115	// FP32 vec4 fast path. Stages the psi weights into shared once, then loads
116	// param/state/grad as float4 (one 128-bit transaction per 4 elements) and CALLS
117	// the canonical neuralgrok_psi_forward<H> + neuralgrok_apply_step 4× on the
118	// register lanes. The math is NOT re-typed here (single-source guard), only the
119	// global traffic is widened and the weights are shared-staged.
120	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_NEURALGROK_MIN_BLOCKS)
121	neuralgrok_kernel_vec4_fp32(
122	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
123	    const float4* grad4,
124	    const float* W1, const float* b1, const float* W2, float b2,
125	    float alpha, float beta,
126	    float lr, float beta1_a, float beta2_a, float eps, float wd,
127	    float bc1, float bc2, int64_t N4
128	) {
129	    __shared__ float sW1[NG_H];
130	    __shared__ float sb1[NG_H];
131	    __shared__ float sW2[NG_H];
132	    ng_stage_psi_weights<NG_H>(W1, b1, W2, sW1, sb1, sW2);
133	
134	    const int64_t stride = prim::grid_stride();
135	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
136	        float4 p = prim::ld_f32v4(param4 + i);
137	        float4 m = prim::ld_f32v4(exp_avg4 + i);
138	        float4 v = prim::ld_f32v4(exp_avg_sq4 + i);
139	        float4 g = prim::ldg_f32v4(grad4 + i);
140	        ::grokking::sm90::sg_sanitize_grad4(g);
141	        #pragma unroll
142	        for (int u = 0; u < 4; ++u) {
143	            const float ag = fabsf((&g.x)[u]);
144	            const float s = neuralgrok_psi_forward<NG_H>(ag, sW1, sb1, sW2, b2);
145	            neuralgrok_apply_step(&p.x, &m.x, &v.x, &g.x, s,
146	                                  alpha, beta, lr, beta1_a, beta2_a, eps, wd,
147	                                  bc1, bc2, u);
148	        }
149	        prim::st_f32v4(param4 + i, p);
150	        prim::st_f32v4(exp_avg4 + i, m);
151	        prim::st_f32v4(exp_avg_sq4 + i, v);
152	    }
153	}
154	
155	void launch_neuralgrok_step(
156	    torch::Tensor& param,
157	    torch::Tensor& exp_avg,
158	    torch::Tensor& exp_avg_sq,
159	    const torch::Tensor& grad,
160	    const torch::Tensor& psi_W1,
161	    const torch::Tensor& psi_b1,
162	    const torch::Tensor& psi_W2,
163	    float psi_b2,
164	    float alpha, float beta,
165	    float lr, float beta1_a, float beta2_a, float eps, float wd,
166	    float bc1, float bc2
167	) {
168	    const int64_t N = param.numel();
169	    if (N == 0) return;
170	
171	    auto stream = at::cuda::getCurrentCUDAStream().stream();
172	
173	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
174	    prim::L2PersistScope l2(stream,
175	        exp_avg.data_ptr(), exp_avg.nbytes(),
176	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
177	
178	    const int block = SG_TUNED_BLOCK_SIZE;
179	    const int grid = static_cast<int>(
180	        std::min<int64_t>(65535, (N + block - 1) / block));
181	
182	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
183	                          grad.scalar_type() == torch::kFloat32;
184	
185	    // Autotuner picks the vector width: width 4 + 16B-aligned all-FP32 takes the
186	    // float4 fast path; otherwise the SG_TUNED_UNROLL scalar path runs. Both
187	    // stage the psi weights into shared once per block.
188	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
189	        prim::is_vec4_alignable(param.data_ptr(), N) &&
190	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
191	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
192	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
193	        const int64_t N4 = N / 4;
194	        const int grid4 = static_cast<int>(
195	            std::min<int64_t>(65535, (N4 + block - 1) / block));
196	        neuralgrok_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
197	            reinterpret_cast<float4*>(param.data_ptr<float>()),
198	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
199	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
200	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
201	            psi_W1.data_ptr<float>(),
202	            psi_b1.data_ptr<float>(),
203	            psi_W2.data_ptr<float>(),
204	            psi_b2,
205	            alpha, beta, lr, beta1_a, beta2_a, eps, wd, bc1, bc2, N4);
206	        SG_LAUNCH_CHECK(stream);
207	        return;
208	    }
209	
210	    AT_DISPATCH_FLOATING_TYPES_AND2(
211	        at::ScalarType::Half, at::ScalarType::BFloat16,
212	        param.scalar_type(), "neuralgrok_step", [&] {
213	            neuralgrok_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
214	                <<<grid, block, 0, stream>>>(
215	                param.data_ptr<scalar_t>(),
216	                exp_avg.data_ptr<float>(),
217	                exp_avg_sq.data_ptr<float>(),
218	                grad.data_ptr<scalar_t>(),
219	                psi_W1.data_ptr<float>(),
220	                psi_b1.data_ptr<float>(),
221	                psi_W2.data_ptr<float>(),
222	                psi_b2,
223	                alpha, beta, lr, beta1_a, beta2_a, eps, wd, bc1, bc2, N);
224	            SG_LAUNCH_CHECK(stream);
225	        });
226	}
227	
228	
229	// Amplifier-only: amplified[i] = psi(|grad[i]|) * grad[i], where
230	// psi is the 1-hidden-layer network (W1,b1,W2,b2) with ReLU.
231	// alpha, beta scale the amplified gradient: out = alpha * psi(|g|) * g + beta * g
232	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_NEURALGROK_MIN_BLOCKS)
233	neuralgrok_amplifier_kernel(
234	    const float* grad, float* amplified,
235	    const float* W1, const float* b1, const float* W2, float b2_scalar,
236	    float alpha, float beta, int64_t N
237	) {
238	    __shared__ float sW1[NG_H];
239	    __shared__ float sb1[NG_H];
240	    __shared__ float sW2[NG_H];
241	    ng_stage_psi_weights<NG_H>(W1, b1, W2, sW1, sb1, sW2);
242	
243	    const int64_t stride = prim::grid_stride();
244	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
245	        float g = ::grokking::sm90::sg_sanitize_grad(grad[i]);
246	        float ag = fabsf(g);
247	        float s = neuralgrok_psi_forward<NG_H>(ag, sW1, sb1, sW2, b2_scalar);
248	        amplified[i] = alpha * s * g + beta * g;
249	    }
250	}
