252	void launch_fused_neuralgrok_amplifier(
253	    torch::Tensor grad, torch::Tensor amplified,
254	    torch::Tensor amplifier_w1, torch::Tensor amplifier_b1,
255	    torch::Tensor amplifier_w2, torch::Tensor amplifier_b2,
256	    int hidden_dim, float alpha, float beta
257	) {
258	    const int64_t N = grad.numel();
259	    if (N == 0) return;
260	    auto stream = at::cuda::getCurrentCUDAStream().stream();
261	    const int block = SG_TUNED_BLOCK_SIZE;
262	    const int grid = static_cast<int>(
263	        std::min<int64_t>(65535, (N + block - 1) / block));
264	    float b2_val = amplifier_b2.item<float>();
265	    neuralgrok_amplifier_kernel<<<grid, block, 0, stream>>>(
266	        grad.data_ptr<float>(), amplified.data_ptr<float>(),
267	        amplifier_w1.data_ptr<float>(), amplifier_b1.data_ptr<float>(),
268	        amplifier_w2.data_ptr<float>(), b2_val,
269	        alpha, beta, N);
270	    SG_LAUNCH_CHECK(stream);
271	}
