309	// Full fused step: psi amplification + Adam update in a single kernel launch.
310	void launch_fused_neuralgrok_full_step(
311	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
312	    torch::Tensor grad,
313	    torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2,
