template <typename GradT>
__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
sg15_sweep_a_kernel(
    float* mu_out, const GradT* grad, const float* sharpness,
    const float* W1, const float* b1, const float* W2, float b2,
    float rescale, float* sharp_partial, int64_t N
) {
    __shared__ float sW1[SG15_H * 2];
    __shared__ float sb1[SG15_H];
    __shared__ float sW2[SG15_H];
    sg15_stage_phi_weights<SG15_H>(W1, b1, W2, sW1, sb1, sW2);

    float sl = 0.0f;
    const int64_t stride = prim::grid_stride();
    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
        SG_SANITIZE_GRAD_INPLACE(grad, i);
        const float g = static_cast<float>(grad[i]);
        const float s = sharpness[i];
        // Apply the trained rescale here (SharpnessMetaNet defines the
        // correction as rescale*MLP), mirroring SG11's mu_metanet kernel.
        // Previously rescale was dropped before this kernel, so mu_buf held the
        // bare MLP output (the H100 parity gate caught mu == MLP, not rescale*MLP).
        const float mu_val =
            rescale * sg15_phi_forward<SG15_H>(g, s, sW1, sb1, sW2, b2);
        sg15_sweep_a_step(mu_out, grad, mu_val, i, sl);
    }
    float r = prim::block_reduce_sum_f32(sl);
    if (threadIdx.x == 0) atomicAdd(sharp_partial, r);
}

template <typename ParamT, typename GradT, int UNROLL>
__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
sg15_sweep_b_kernel(
    ParamT* param, float* exp_avg, float* exp_avg_sq,
    const GradT* grad, const float* mu,
    float gate_global, float alpha_base, float alpha_max,
    float lr, float beta1, float beta2, float eps, float wd,
    float bc1, float bc2, int64_t N
) {
    const int64_t stride = prim::grid_stride() * UNROLL;
    const int64_t base0 = prim::grid_stride_index() * UNROLL;
    for (int64_t base = base0; base < N; base += stride) {
        #pragma unroll
        for (int u = 0; u < UNROLL; ++u) {
            const int64_t i = base + u;
            if (i < N) {
                SG_SANITIZE_GRAD_INPLACE(grad, i);
                sg15_sweep_b_step(param, exp_avg, exp_avg_sq, grad, mu,
                                  gate_global, alpha_base, alpha_max,
                                  lr, beta1, beta2, eps, wd, bc1, bc2, i);
            }
        }
    }
}

// FP32 vec4 sweep B: float4 traffic on param/state/grad/mu, canonical
// sg15_sweep_b_step CALLED 4× on the register lanes. Math is NOT re-typed here.
__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
sg15_sweep_b_kernel_vec4_fp32(
    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
    const float4* grad4, const float4* mu4,
    float gate_global, float alpha_base, float alpha_max,
    float lr, float beta1, float beta2, float eps, float wd,
    float bc1, float bc2, int64_t N4
) {
    const int64_t stride = prim::grid_stride();
    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
        float4 p  = prim::ld_f32v4(param4 + i);
        float4 m  = prim::ld_f32v4(exp_avg4 + i);
        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
        float4 g  = prim::ldg_f32v4(grad4 + i);
        float4 mu = prim::ldg_f32v4(mu4 + i);
        ::grokking::sm90::sg_sanitize_grad4(g);
        #pragma unroll
        for (int u = 0; u < 4; ++u) {
            sg15_sweep_b_step(&p.x, &m.x, &v.x, &g.x, &mu.x,
                              gate_global, alpha_base, alpha_max,
                              lr, beta1, beta2, eps, wd, bc1, bc2, u);
        }
        prim::st_f32v4(param4 + i, p);
        prim::st_f32v4(exp_avg4 + i, m);
        prim::st_f32v4(exp_avg_sq4 + i, v);
    }
}

void launch_supergrok15_step(
    torch::Tensor& param,
    torch::Tensor& exp_avg,
    torch::Tensor& exp_avg_sq,
    torch::Tensor& mu_buf,
    const torch::Tensor& grad,
    const torch::Tensor& sharpness,
    const torch::Tensor& phi_W1,
    const torch::Tensor& phi_b1,
    const torch::Tensor& phi_W2,
    float phi_b2,
    float rescale,
    torch::Tensor& sharp_partial,
    float gate_global,
    float alpha_base, float alpha_max,
    float lr, float beta1, float beta2, float eps, float wd,
    float bc1, float bc2
) {
    const int64_t N = param.numel();
    if (N == 0) return;

2654	__global__ void moe_dynamic_expert_bwd_kernel(
2655	    const float* __restrict__ d_output,
2656	    const float* __restrict__ input,
2657	    const int* __restrict__ expert_indices,
2658	    const float* __restrict__ routing_weights,
2659	    const float* __restrict__ expert_w1, const float* __restrict__ expert_b1,
2660	    const float* __restrict__ expert_w2, const float* __restrict__ expert_b2,
2661	    float* __restrict__ d_input, float* __restrict__ d_expert_w1,
2662	    float* __restrict__ d_expert_b1, float* __restrict__ d_expert_w2,
2663	    float* __restrict__ d_expert_b2,
2664	    int N, int d_in, int hidden, int d_out
2665	) {
2666	    const int t = blockIdx.x;
2667	    if (t >= N) return;
2668	    const int lane = threadIdx.x;
2669	    const int nthreads = blockDim.x;
2670	    const int e = expert_indices[t];
2671	    const float rw = routing_weights[t];
2672	
2673	    const float* x   = input + static_cast<long>(t) * d_in;
2674	    const float* W1  = expert_w1 + static_cast<long>(e) * hidden * d_in;
2675	    const float* b1  = expert_b1 + static_cast<long>(e) * hidden;
2676	    const float* W2  = expert_w2 + static_cast<long>(e) * d_out * hidden;
2677	    const float* dy_row = d_output + static_cast<long>(t) * d_out;
2678	
2679	    float* dW1 = d_expert_w1 + static_cast<long>(e) * hidden * d_in;
2680	    float* db1 = d_expert_b1 + static_cast<long>(e) * hidden;
2681	    float* dW2 = d_expert_w2 + static_cast<long>(e) * d_out * hidden;
2682	    float* db2 = d_expert_b2 + static_cast<long>(e) * d_out;
2683	
2684	    // h[j] = relu(W1 x + b1)[j], hmask[j] = [z1>0]   (recompute forward act).
2685	    extern __shared__ float smem[];
2686	    float* h    = smem;             // [hidden]
2687	    float* dz1  = smem + hidden;    // [hidden]
2688	    for (int j = lane; j < hidden; j += nthreads) {
2689	        float acc = b1[j];
2690	        const float* w1row = W1 + static_cast<long>(j) * d_in;
2691	        for (int k = 0; k < d_in; ++k) acc += w1row[k] * x[k];
2692	        h[j] = acc > 0.0f ? acc : 0.0f;
2693	        dz1[j] = 0.0f;
2694	    }
2695	    __syncthreads();
2696	
2697	    // dy = rw * d_output ; db2 += dy ; dW2 += dy ⊗ h ; accumulate dh into dz1.
2698	    for (int o = lane; o < d_out; o += nthreads) {
2699	        const float dy = rw * dy_row[o];
2700	        atomicAdd(&db2[o], dy);
2701	        const float* w2row = W2 + static_cast<long>(o) * hidden;
2702	        float* dw2row = dW2 + static_cast<long>(o) * hidden;
2703	        for (int j = 0; j < hidden; ++j) {
2704	            atomicAdd(&dw2row[j], dy * h[j]);
2705	            // dh_j = Σ_o W2[o,j] dy ; gate by relu mask (h[j]>0).
2706	            if (h[j] > 0.0f) atomicAdd(&dz1[j], w2row[j] * dy);
2707	        }
2708	    }
2709	    __syncthreads();
2710	
2711	    // dW1 += dz1 ⊗ x ; db1 += dz1 ; d_input[t] = W1ᵀ dz1.
2712	    for (int j = lane; j < hidden; j += nthreads) {
2713	        const float g = dz1[j];
2714	        atomicAdd(&db1[j], g);
2715	        float* dw1row = dW1 + static_cast<long>(j) * d_in;
2716	        for (int k = 0; k < d_in; ++k) atomicAdd(&dw1row[k], g * x[k]);
2717	    }
2718	    __syncthreads();
2719	    float* dx = d_input + static_cast<long>(t) * d_in;
2720	    for (int k = lane; k < d_in; k += nthreads) {
2721	        float acc = 0.0f;
2722	        for (int j = 0; j < hidden; ++j) {
2723	            acc += W1[static_cast<long>(j) * d_in + k] * dz1[j];
2724	        }
2725	        dx[k] = acc;
2726	    }
2727	}
