2729	void moe_dynamic_expert_bwd(
2730	    torch::Tensor d_output, torch::Tensor input,
2731	    torch::Tensor expert_indices, torch::Tensor routing_weights,
2732	    torch::Tensor expert_w1, torch::Tensor expert_b1,
2733	    torch::Tensor expert_w2, torch::Tensor expert_b2,
2734	    torch::Tensor d_input, torch::Tensor d_expert_w1,
