353	//
354	//  Both attention kernels read the per-thread query vector qv[0..head_dim)
355	//  REPEATEDLY (once per top-k entry and once per window token). That makes the
356	//  query the reused global->shared staging load — the prime cp.async target.
357	//  Each thread stages its own head_dim-float query slice into its private slot
358	//  qsh[threadIdx.x*head_dim .. +head_dim) with hand-issued cp.async.ca (4B)
359	//  copies, split into `kCsaAsyncDepth` groups kept in flight so the query-load
360	//  latency overlaps the first key's address math. After cp_async_wait_all the
361	//  staged slice is BYTE-IDENTICAL to a synchronous load of qv (no numeric
362	//  change). The streaming K/V reads stay direct (read once, no reuse benefit).
363	//
364	//  NOTE: these kernels are 1-thread-per-(query,head) with no __syncthreads, so
365	//  each thread waits only on ITS OWN cp.async groups — no block-wide barrier
366	//  is needed (and none exists) to make the private slot visible to the owner.
367	__device__ __forceinline__ const float* csa_stage_query_async(
368	    float* qsh,              // dynamic shared: [blockDim.x * head_dim]
369	    const float* __restrict__ qv_global,  // [head_dim] this thread's query
370	    int head_dim
371	) {
372	    float* qslot = qsh + threadIdx.x * head_dim;
373	    // Split head_dim into kCsaAsyncDepth roughly-equal chunks; commit each as
374	    // its own group so up to kCsaAsyncDepth copies are in flight at once.
375	    const int chunk = (head_dim + kCsaAsyncDepth - 1) / kCsaAsyncDepth;
376	    #pragma unroll
377	    for (int g = 0; g < kCsaAsyncDepth; ++g) {
378	        const int e0 = g * chunk;
379	        const int e1 = (e0 + chunk < head_dim) ? (e0 + chunk) : head_dim;
380	        for (int e = e0; e < e1; ++e) {
381	            prim::cp_async_ca_4(&qslot[e], &qv_global[e]);
382	        }
383	        prim::cp_async_commit();
384	    }
385	    prim::cp_async_wait_all();  // drain all groups: qslot now == qv (byte-exact)
386	    return qslot;
387	}
