408	    int head_dim, int topk, int csa_window
409	) {
410	    const int gid = blockIdx.x * blockDim.x + threadIdx.x;
411	    const int total = N * num_heads;
412	    // §4.2 cp.async query staging buffer + SMEM-staged online-softmax
413	    // accumulator. Layout: [blockDim.x * head_dim] query slots, then
414	    // [blockDim.x * head_dim] accumulator slots. The accumulator was a
415	    // CSA_MAX_D_MODEL (=64) per-thread register array that pinned register
416	    // pressure (and spilled to local on real ptxas); moving it into this
417	    // thread's private shared slot is BIT-IDENTICAL — the same float adds in
418	    // the same order, only the storage class changes (register/local -> smem).
419	    extern __shared__ float csa_qsh[];
420	    if (gid >= total) return;
421	    const int t = gid / num_heads;
422	    const int h = gid % num_heads;
423	    const int hoff = h * head_dim;
424	
425	    const float scale = rsqrtf(static_cast<float>(head_dim));
426	
427	    float* acc = csa_qsh + (blockDim.x + threadIdx.x) * head_dim;  // private slot
428	    #pragma unroll
429	    for (int e = 0; e < head_dim; e++) acc[e] = 0.0f;
430	    float run_max = -INFINITY, run_denom = 0.0f;
431	
432	    // Background-load this thread's reused query slice into shared via cp.async.
433	    const float* qv = csa_stage_query_async(
434	        csa_qsh, q + t * d_model + hoff, head_dim);
435	
436	    // Selected compressed entries.
437	    for (int i = 0; i < topk; i++) {
438	        const int s = sel_idx[t * topk + i];
439	        if (s < 0 || s >= Nc) continue;
440	        alg::sg2_attention_score_and_accumulate(
441	            qv, c_k + s * d_model + hoff, c_v + s * d_model + hoff,
442	            &run_max, &run_denom, acc, scale, head_dim);
443	    }
444	    // Causal sliding window over raw tokens [t-csa_window+1 .. t].
445	    const int w0 = (t - csa_window + 1 > 0) ? (t - csa_window + 1) : 0;
