448	            qv, win_k + s * d_model + hoff, win_v + s * d_model + hoff,
449	            &run_max, &run_denom, acc, scale, head_dim);
450	    }
451	    alg::sg2_softmax_finalize(acc, run_denom, head_dim);
452	
453	    // Out projection (this head's slice contributes to all output channels).
454	    // We write the head-local attention output back into a temporary head slot
455	    // of csa_ctx, then a second pass applies out_W. To keep one kernel, we
456	    // fold out_W here per output channel d that this head owns is insufficient;
457	    // instead store the concatenated heads then project. Store head slice:
458	    for (int e = 0; e < head_dim; e++)
459	        csa_ctx[t * d_model + hoff + e] = acc[e];
460	    (void)out_W;  // applied by attn_out_proj_kernel after head concatenation
461	}
